  "headline": "Oxaliplatin is not on FDA's shortage list as of 2026-10-21",
  "headline_cites": ["D3"],
  "sentences": [
    {
      "text": "FDA's records show oxaliplatin is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale General holds 57 vials of oxaliplatin 5 mg/mL, 10 mL at 2.8 per day, providing 20 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale Lakeside holds 8 vials of the same presentation at 0.9 per day, providing 8.6 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 6 vials of 5 mg/mL, 10 mL from Corvale General to Corvale Lakeside.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale General can spare 6 vials while keeping two weeks of supply, and Corvale Lakeside would reach 15 days after the transfer.",
      "cites": ["D4"]
    },
    {
      "text": "Alternate manufacturers Accord Healthcare Inc. and Apotex Corp. are not on FDA's shortage list today, but their labels name no plant we could place.",
      "cites": ["D5", "D6"]
    }
  ]
}
